import {HOUSEHOLD_PROFILES,householdCosts,householdDue,payroll} from './household.js';
import {salaryGross,salaryIncome,expenses,age} from './engine.js';
export function renderHousehold(s,{won,escape:e}){if(!s.household)return '';const h=s.household,c=householdCosts(s),p=payroll(s,salaryGross(s)),basic=Math.round(s.living*s.cpi),food=Math.round(basic*.38),utilities=Math.round(basic*.18),transport=Math.round(basic*.16),other=basic-food-utilities-transport;
 const rows=[['식비 · 생활비 모형',food],['공과금·통신 · 생활비 모형',utilities],['교통 · 생활비 모형',transport],['기타 소비 · 생활비 모형',other],['주거비·관리비',Math.round((s.home?(s.homeMaintenance??150000):s.rent)*s.cpi)],['차량 유지비',s.car?Math.round((s.vehicle?.maintenanceBase??200000)*s.cpi):0],['의료비 모형',c.medical],['민간보험 모형',c.privateInsurance],['자동차 보험료 모형',c.carInsurance],['주택 보험료 모형',c.homeInsurance]];
 return `<details class="finance-help"><summary>월 가계 지출 · −${won(expenses(s))}</summary><p>${h.mode==='random'?e(HOUSEHOLD_PROFILES.find(x=>x.id===h.profile)?.name||''):'직접 설정 · 기본 가계'} · 배정 확률과 재산·급여·지출은 게임 가정입니다.</p><div class="household-budget">${rows.map(([label,n])=>`<div><span>${label}</span><b>−${won(n)}</b></div>`).join('')}<div><span>세전 급여</span><b>${won(p.gross)}</b></div><div><span>급여 공제 · 사회보험/세금 모형</span><b>−${won(p.deduction)}</b></div><div><span>실수령 급여</span><b>${won(salaryIncome(s))}</b></div><div><span>시작 가정의 기존 부채</span><b>${won(h.debtBalance+h.debtInterest)}</b></div><div><span>기존 부채 다음 월 원리금</span><b>−${won(householdDue(s))}</b></div></div><p>급여 공제는 세전 급여에서 한 번만 차감합니다. 소비 지출과 원금 상환은 별도입니다. 기본 생활비의 항목 비중은 분류용 게임 설정입니다. 비용·보험·공제는 실제 당시 통계·보험상품·세법이 아닙니다.</p><p>보험은 가상 입원비만 80%, 연간 물가 조정 1,000만원 한도에서 차감합니다. 사기·실직·자동차 수리는 보장하지 않습니다. 기존 부채는 가정한 연 5%·원금 120회 분할이며 실제 대출상품이 아닙니다. 미납 이자는 부채로 남습니다.</p><button class="btn secondary small" data-insurance-review="yes" ${s.ended||s.pending||age(s)<19?'disabled':''}>${h.privateInsurance?'민간보험 모형 해지 확인':'민간보험 모형 가입 확인'}</button><p><a href="https://www.korea.kr/briefing/policyBriefingView.do?newsId=156733201" target="_blank" rel="noopener noreferrer">2025 가계금융복지조사 · 인구/가구 기준 확인 ↗</a></p></details>`;
}
